import re

def _norm(text):
    text = re.sub(r'[^a-z0-9 ]', '', text.lower())
    return ' '.join(text.split())

def split_examples(examples, test_ids):
    seen = set()
    unique = []
    for ex in examples:
        key = _norm(ex['prompt'])
        if key not in seen:
            seen.add(key)
            unique.append((ex['id'], key))
    test_keys = {key for eid, key in unique if eid in test_ids}
    test = [eid for eid, key in unique if eid in test_ids]
    train = [eid for eid, key in unique if eid not in test_ids and key not in test_keys]
    return train, test
